svg.script:
function update() {
  var now = new Date();
  var dOpts = { day:'2-digit', month:'short', year:'numeric' };
  var tOpts = { hour:'2-digit', minute:'2-digit', second:'2-digit', hour12:false };
  var txt = now.toLocaleDateString('en-GB', dOpts)
          + ' '
          + now.toLocaleTimeString('en-GB', tOpts);
  document.getElementById('clock').textContent = txt;
}
setInterval(update, 1000);
update();
